PANDAS_EXT_HELP = [
    "# pandas_ext - توسعة حزمة pandas: أصنافها ودوالها وطرقها وثوابتها التي لا تغطّيها مكتبات APL الأخرى",
]

_PANDAS_EXT_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _pandas_ext_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in PANDAS_EXT_CONSTS:
        return PANDAS_EXT_CONSTS[word]
    if word in PANDAS_EXT_FUNCS:
        return PANDAS_EXT_FUNCS[word] + (open_paren or "")
    return match.group(0)


def PANDAS_EXT_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _PANDAS_EXT_TOKEN.sub(_pandas_ext_replace, text)
